style.css:
@-moz-document domain("kisskh.do") {
/* 1. Main Backgrounds & App Structure */
    body, html, #app, .v-application, .v-main {
        background-color: #fff5f7 !important; /* Soft Pastel Baby Pink Wash */
        color: #5e5256 !important; /* Muted Cocoa Rose Text */
    }

    /* 2. Top Header Navigation Bar */
    header, .v-app-bar, .navbar, .v-navigation-drawer {
        background-color: #ffffff !important;
        border-bottom: 2px solid #ffe3e8 !important; /* Very Soft Pastel Pink Border */
    }

    /* 3. Movie Grid Cards & Episode Lists */
    .v-card, .episode-item, .card-movie, .list-group-item {
        background-color: #ffffff !important;
        border: 2px solid #fff0f2 !important; /* Barely-there Pastel Border */
        border-radius: 12px !important;
        box-shadow: 0 4px 10px rgba(255, 192, 203, 0.1) !important;
        transition: all 0.2s ease-in-out !important;
    }

    /* Hover effect on content tiles */
    .v-card:hover, .episode-item:hover {
        border-color: #ffb7c5 !important; /* Delicate Soft Pink Accent */
        background-color: #fffafb !important;
        transform: translateY(-2px);
    }

    /* 4. Pastel Pink Typography, Buttons & Labels */
    a, .v-btn, .primary--text, h1, h2, .episode-title, .v-icon {
        color: #ffb7c5 !important; /* Soft Pastel Cherry Blossom Pink */
    }
    
    a:hover {
        color: #ffa3b5 !important; /* Slightly deeper pink on hover */
    }

    /* 5. Custom Movie Player Wrapping Frame */
    .player-container, #player, .video-holder, .iframe-container {
        background: #1c191a !important; /* Soft Off-Black Player for comfortable viewing */
        border: 4px solid #ffe3e8 !important; /* Gentle Pastel Pink Frame */
        border-radius: 12px !important;
        box-shadow: 0 8px 24px rgba(255, 183, 197, 0.2) !important;
    }

    /* 6. Form Inputs & Search Toolbars */
    input, select, textarea, .v-input {
        background-color: #ffffff !important;
        color: #5e5256 !important;
        border: 2px solid #ffe3e8 !important;
        border-radius: 8px !important;
    }

    /* 7. Hide clutter placeholders */
    .ads-container, [id*="ad-"], [class*="banner-ad"], .native-ad {
        display: none !important;
    }
}
